from dsl import *
P = ["optional-geography"]

E(125, "plate-tectonics", "geog1-1", P + ["prelims-gs"], "The continents were once one", "Geomorphology: from drift to plates", "mountain",
  ["Alfred Wegener, The Origin of Continents and Oceans (1915)", "NCERT Class 11, Fundamentals of Physical Geography, ch. 4"],
  "A: Look at a map, and South America seems to fit into Africa. | B: Alfred Wegener took that seriously.",
  [TL("From drift to plates", [(1912, "Wegener: continental drift", "1912"), (1960, "Hess: sea-floor spreading", "1960"), (1967, "Plate tectonics", "1967")],
      "A: Wegener proposed continental drift in 1912, with one supercontinent, Pangaea. | B: In the 1960s, Harry Hess's sea-floor spreading led to plate tectonics."),
   CH("Plate boundaries", "Three kinds", [("Divergent", "Plates move apart: mid-ocean ridges", "Divergent"), ("Convergent", "Plates collide: the Himalaya", "Convergent"), ("Transform", "Plates slide past: San Andreas", "Transform")],
      "A: At divergent boundaries, plates move apart. At convergent ones, they collide, as India did with Asia. | B: At transform boundaries, they slide past each other."),
   QT("Why it was doubted", "He couldn't explain what force moved the continents.",
      "A: Wegener's idea was rejected for decades, | B: because he couldn't explain the force that moved continents.")],
  QZ("The Himalaya formed at which type of plate boundary?", ["Divergent", "Convergent", "Transform", "Passive"], 1,
     "Right. Convergent: the Indian plate colliding with the Eurasian plate.", "A: Your turn. | B: Which type of boundary?"))

E(126, "koppen", "geog1-2", P + ["prelims-gs"], "Five letters sort the world's climates", "Climatology: Köppen's scheme", "globe",
  ["Wladimir Köppen's climate classification", "NCERT Class 11, Fundamentals of Physical Geography, ch. 12"],
  "A: How do you sort every climate on Earth? | B: Wladimir Köppen used five capital letters.",
  [CH("The five groups", "Köppen", [("A tropical · B dry", "Hot and wet · deserts and steppes", "tropical"), ("C warm temperate · D cold", "Mild winters · snowy winters", "temperate"), ("E polar", "Tundra and ice", "polar")],
      "A: A for tropical, B for dry, C for warm temperate. | B: D for cold, snowy climates, and E for polar."),
   CH("In India", "Examples", [("Amw", "Monsoon with short dry season: west coast", "Amw"), ("BWhw", "Hot desert: western Rajasthan", "BWhw")],
      "A: India's west coast is A-m-w, monsoon with a short dry season. | B: Western Rajasthan is B-W-h-w, a hot desert."),
   QT("The basis", "Temperature and rainfall, matched to natural vegetation.",
      "A: Köppen based it on temperature and rainfall, | B: matched to natural vegetation.")],
  QZ("In Köppen's scheme, the letter B stands for:", ["Tropical", "Dry", "Cold", "Polar"], 1,
     "Right. Dry climates.", "A: Your turn. | B: What does B stand for?"))

E(127, "salinity-currents", "geog1-3", P + ["prelims-gs"], "Warm currents warm coasts, cold ones dry them", "Oceanography: salinity and currents", "globe",
  ["NCERT Class 11, Fundamentals of Physical Geography, ch. 13–14"],
  "A: Why is Peru's coast a desert, right next to the ocean? | B: A cold current runs along it.",
  [ST("Salinity", [(35, " ‰", "average ocean salinity (parts per thousand)", "35")],
      "A: The oceans average about 35 parts per thousand of salt. | B: Evaporation raises it. Rivers and rain lower it."),
   CH("Two currents", "Compare", [("Gulf Stream", "Warm: keeps north-west Europe mild", "Gulf"), ("Humboldt (Peru)", "Cold: helps make the Atacama dry", "Humboldt")],
      "A: The warm Gulf Stream keeps north-western Europe mild. | B: The cold Humboldt current helps make the Atacama one of the driest places on Earth."),
   QT("Cold water, more fish", "Upwelling brings nutrients to the surface.",
      "A: Cold currents often come with upwelling, | B: which brings nutrients up, and with them, fish.")],
  QZ("The Humboldt (Peru) current is:", ["Warm", "Cold", "A tide", "A wind"], 1,
     "Right. A cold current.", "A: Your turn. | B: Is it warm or cold?"))

E(128, "wallace-line", "geog1-4", P, "An invisible line splits Asia's animals from Australia's", "Biogeography: the Wallace Line", "forest",
  ["Alfred Russel Wallace, 'On the Zoological Geography of the Malay Archipelago' (1859)"],
  "A: Bali and Lombok are only about 35 kilometres apart. | B: Yet their animals are strikingly different.",
  [TL("The line", [(1859, "Wallace describes it", "1859")],
      "A: In 1859, Alfred Russel Wallace drew a line through the Malay Archipelago. | B: Asian animals on one side, Australian on the other."),
   MP([[118, -5], 2.2], [("Bali", [116, -8.5], 4.0)], [([115.1, -8.4], "Bali · Asian side", "Bali"), ([116.3, -8.6], "Lombok · Australian side", "Lombok")],
      "A: Bali sits on the Asian side. | B: Lombok, on the Australian side. A deep-water channel kept them apart, even in the ice ages."),
   CH("Biogeography", "Covers", [("Soils and vegetation", "", "Soils"), ("Deforestation and conservation", "", "Deforestation")],
      "A: The topic also covers soils and vegetation, | B: and deforestation and conservation.")],
  QZ("The Wallace Line separates the animals of:", ["Africa and Asia", "Asia and Australia", "Europe and Asia", "The Americas"], 1,
     "Right. Asia and Australia.", "A: Your turn. | B: What does it separate?"),
  note="Map is schematic land-only; no borders drawn.")

E(129, "ipat", "geog1-5", P, "Impact equals population times affluence times technology", "Environmental geography: IPAT", "forest",
  ["Paul Ehrlich and John Holdren, 'Impact of Population Growth', Science (1971)"],
  "A: What drives our impact on the planet? | B: In 1971, one equation tried to answer.",
  [QT("IPAT", "I = P × A × T",
      "A: Impact equals population, times affluence, times technology. | B: Ehrlich and Holdren set it out in 1971."),
   CH("What it shows", "Three levers", [("Population", "How many of us", "Population"), ("Affluence", "How much each consumes", "Affluence"), ("Technology", "How clean the production is", "Technology")],
      "A: Impact grows with numbers and with consumption. | B: Cleaner technology can bring it down."),
   QT("Carrying capacity", "The largest population an environment can support without degrading.",
      "A: Link it to carrying capacity: | B: the largest population an environment can support without damage.")],
  QZ("In IPAT, 'A' stands for:", ["Area", "Affluence", "Agriculture", "Atmosphere"], 1,
     "Right. Affluence, or consumption per person.", "A: Your turn. | B: What does A stand for?"))

E(130, "human-geog-perspectives", "geog1-6", P, "Geography moved from describing regions to modelling them", "Perspectives in human geography", "compass",
  ["Richard Hartshorne, The Nature of Geography (1939)", "Fred Schaefer, 'Exceptionalism in Geography' (1953)"],
  "A: Is geography about what makes each place unique, | B: or about general laws? The discipline has swung both ways.",
  [TL("The swings", [(1939, "Hartshorne: areal differentiation", "1939"), (1953, "Schaefer: search for laws", "1953")],
      "A: In 1939, Hartshorne said geography studies how areas differ. | B: In 1953, Fred Schaefer argued it should seek laws, opening the quantitative revolution."),
   CH("Then came", "Reactions", [("Behavioural", "How people perceive space", "Behavioural"), ("Radical", "Inequality and power", "Radical"), ("Humanistic", "Meaning and place", "Humanistic")],
      "A: Behavioural geographers studied how people perceive space. Radical geographers looked at inequality. | B: Humanistic geographers, at meaning and place."),
   QT("Also", "Cultural regions and welfare: the syllabus lists both.",
      "A: The syllabus also lists cultural regions | B: and welfare approaches.")],
  QZ("Who wrote 'Exceptionalism in Geography' (1953)?", ["Hartshorne", "Schaefer", "Harvey", "Tuan"], 1,
     "Right. Fred Schaefer.", "A: Your turn. | B: Who wrote it?"))

E(131, "von-thunen", "geog1-7", P, "Crops form rings around a city", "Economic geography: von Thünen", "farm",
  ["J. H. von Thünen, The Isolated State (1826)"],
  "A: Why do vegetables grow near cities, and cattle graze far away? | B: Von Thünen explained it in 1826.",
  [TL("The model", [(1826, "The Isolated State", "1826")],
      "A: Johann Heinrich von Thünen imagined one city on a flat plain. | B: Farmers choose crops by the cost of getting them to market."),
   CH("The rings", "From the city out", [("Market gardens, dairy", "Perishable, close in", "Market"), ("Forest", "Heavy fuel wood", "Forest"), ("Grain, then ranching", "Further out", "Grain")],
      "A: Perishables and dairy near the city. Then forest, because wood is heavy. | B: Then grain, and ranching farthest out."),
   QT("Key idea", "Location rent falls with distance from the market.",
      "A: The key idea: | B: land rent falls as distance to the market rises.")],
  QZ("In von Thünen's model, the ring nearest the city grows:", ["Wheat", "Perishables and dairy", "Ranching", "Forest"], 1,
     "Right. Perishables and dairy.", "A: Your turn. | B: What grows nearest?"))

E(132, "central-place", "geog1-8", P, "Towns arrange themselves in hexagons", "Settlement geography: central place theory", "village",
  ["Walter Christaller, Central Places in Southern Germany (1933)"],
  "A: Why are big cities far apart, with small towns in between? | B: Walter Christaller had a theory.",
  [TL("The theory", [(1933, "Christaller", "1933")],
      "A: Christaller published central place theory in 1933, | B: from his study of southern Germany."),
   CH("Key ideas", "Central places", [("Threshold", "Minimum customers to survive", "Threshold"), ("Range", "How far people travel for it", "Range"), ("Hexagons", "Market areas without gaps", "Hexagons")],
      "A: Each service needs a threshold of customers, and has a range people will travel. | B: Market areas pack together as hexagons."),
   CH("Principles", "K values", [("K = 3 marketing", "K = 4 transport", "marketing"), ("K = 7 administrative", "", "administrative")],
      "A: He described a marketing principle, a transport principle, | B: and an administrative one.")],
  QZ("In Christaller's theory, market areas are shaped as:", ["Circles", "Squares", "Hexagons", "Triangles"], 2,
     "Right. Hexagons, which fit together without gaps or overlaps.", "A: Your turn. | B: What shape?"))

E(133, "growth-pole", "geog1-9", P, "Growth starts at poles, then spreads, or doesn't", "Regional planning: growth poles", "economy",
  ["François Perroux (1955)", "Gunnar Myrdal, Economic Theory and Underdeveloped Regions (1957)"],
  "A: Should a poor region get many small projects, | B: or one big centre of growth?",
  [TL("Ideas", [(1955, "Perroux: growth poles", "1955"), (1957, "Myrdal: backwash effects", "1957")],
      "A: François Perroux argued in 1955 that growth appears at poles, not everywhere. | B: In 1957, Gunnar Myrdal warned that poles can drain their surroundings."),
   CH("Two effects", "Myrdal", [("Spread", "Growth reaches the hinterland", "Spread"), ("Backwash", "Labour and capital pulled away", "Backwash")],
      "A: Spread effects carry growth outwards. | B: Backwash effects pull labour and capital in, leaving the hinterland poorer."),
   CH("In India", "Planning", [("Multi-level planning", "District and block plans", "Multi")],
      "A: India's answer has included multi-level planning, | B: at district and block levels.")],
  QZ("'Backwash effects' were described by:", ["Perroux", "Myrdal", "Hirschman", "Rostow"], 1,
     "Right. Gunnar Myrdal.", "A: Your turn. | B: Who described backwash effects?"))

E(134, "rank-size", "geog1-10", P, "The second city is half the size of the first, or is it?", "Models: rank-size rule and primate city", "chart",
  ["Mark Jefferson, 'The Law of the Primate City' (1939)", "G. K. Zipf, Human Behavior and the Principle of Least Effort (1949)"],
  "A: Is a country's second city half the size of its first? | B: That's the rank-size rule.",
  [QT("Rank-size rule", "The nth city is 1/n the size of the largest.",
      "A: Zipf's rank-size rule says the city ranked n is one-nth the size of the largest. | B: The second is half, the third a third."),
   TL("Primate city", [(1939, "Mark Jefferson", "1939")],
      "A: Mark Jefferson, in 1939, described primate cities: | B: one city far bigger than all the rest."),
   CH("Other models", "Syllabus", [("Rostow's stages of growth", "1960", "Rostow"), ("Demographic transition", "", "Demographic")],
      "A: The syllabus also covers Rostow's stages of growth, | B: and demographic transition.")],
  QZ("Under the rank-size rule, the third-largest city is about:", ["Half the largest", "A third of the largest", "Twice the largest", "The same size"], 1,
     "Right. One-third.", "A: Your turn. | B: How big is the third city?"))

